// US$ per 1 million tokens, by model. Add a row here when you switch ANALYSE_MODEL.
// This runs BEFORE any document is claimed or sent to Claude: a model without a price
// stops the run here, so no call is ever made whose cost we could not log.
const PRICES = {
  'claude-opus-5-5': { input: 4, output: 20 },
  'claude-sonnet-5-5': { input: 2, output: 10 },
  'claude-haiku-5-5': { input: 0.1, output: 0.5 },
};
// Opus and Sonnet requests ask for server-side fallbacks (header + body field).
const WITH_FALLBACKS = ['claude-opus-5-5', 'claude-sonnet-5-5'];

const model = $env.ANALYSE_MODEL;
const price = PRICES[model];
if (!price) {
  throw new Error(`No price for model "${model}" (ANALYSE_MODEL). Add it to the table in "Look up model price". Nothing was sent to Claude.`);
}
return [{ json: { model, input_usd_per_mtok: price.input, output_usd_per_mtok: price.output, fallbacks: WITH_FALLBACKS.includes(model) } }];

// Builds the Messages API request for one claimed document. Its content comes from this
// run's scan: the claim only takes documents whose current content hash is in it.
const doc = $json;
const price = $('Look up model price').first().json;
const scanned = $('Scan document folders').first().json.documents
  .find((d) => d.kind === doc.kind && d.sourceRef === doc.source_ref);
if (!scanned) throw new Error(`Claimed document ${doc.kind}/${doc.source_ref} is not in this run's scan.`);

const isCv = doc.kind === 'cv';
const documentBlock = scanned.pdfBase64
  ? { type: 'document', source: { type: 'base64', media_type: 'application/pdf', data: scanned.pdfBase64 } }
  : { type: 'text', text: '<document>\n' + (scanned.text ?? '') + '\n</document>' };
const instruction = isCv
  ? 'Record the facts this base CV states.'
  : 'Record what this base cover letter states.';

const headers = { 'anthropic-version': '2026-10-21', 'content-type': 'application/json' };
if (price.fallbacks) headers['anthropic-beta'] = 'server-side-fallback-2026-07-01';
const request = {
  model: price.model,
  max_tokens: 16000,
  output_config: { effort: 'medium', format: { type: 'json_schema', schema: isCv ? doc.cv_schema : doc.cover_letter_schema } },
  system: isCv ? doc.cv_prompt : doc.cover_letter_prompt,
  messages: [{ role: 'user', content: [documentBlock, { type: 'text', text: instruction }] }],
};
if (price.fallbacks) request.fallbacks = 'default';

return {
  json: {
    document_id: doc.id,
    kind: doc.kind,
    source_ref: doc.source_ref,
    claimed_at: doc.claimed_at,
    purpose: isCv ? 'analyse_cv' : 'analyse_cover_letter',
    headers,
    request,
  },
};

// Flattens Claude's HTTP response into simple fields the IF nodes can check.
const res = $json; // statusCode + body, or { error } when the request itself failed
const doc = $('Build analysis request').item.json;
const body = res.body && typeof res.body === 'object' ? res.body : {};
const isObject = (v) => !!v && typeof v === 'object' && !Array.isArray(v);
const isString = (v) => typeof v === 'string';
const stringOrNull = (v) => v === null || isString(v);
const isStringList = (v) => Array.isArray(v) && v.every(isString);
const isList = (v, item) => Array.isArray(v) && v.every((x) => isObject(x) && item(x));

// The answer is the first "text" block (skip any "thinking" blocks before it).
const textBlock = (body.content ?? []).find((block) => block.type === 'text');
let answer = null;
try {
  answer = JSON.parse(textBlock?.text ?? '');
} catch {
  answer = null;
}
const validCv = (a) =>
  stringOrNull(a.headline) && stringOrNull(a.summary) && stringOrNull(a.workRights) &&
  isList(a.education, (e) => [e.qualification, e.institution, e.dates, e.statusText].every(isString)) &&
  isList(a.roles, (r) => [r.title, r.employer, r.dates].every(isString) && isStringList(r.bullets)) &&
  isList(a.projects, (p) => isString(p.name) && isStringList(p.bullets)) &&
  isStringList(a.skills) && isStringList(a.metrics) &&
  isObject(a.contact) && [a.contact.location, a.contact.email, a.contact.phone].every(stringOrNull) && isStringList(a.contact.links);
const validCoverLetter = (a) =>
  isObject(a.previousTarget) &&
  [a.previousTarget.company, a.previousTarget.addressee, a.previousTarget.role].every(stringOrNull) &&
  isStringList(a.reusableParagraphs) && isString(a.toneNotes);
const validJson =
  isObject(answer) && isString(answer.labelSuggestion) && answer.labelSuggestion.trim() !== '' &&
  (doc.kind === 'cv' ? validCv(answer) : validCoverLetter(answer));

const httpOk = typeof res.statusCode === 'number' && res.statusCode >= 200 && res.statusCode < 300;
const stopReason = body.stop_reason ?? null;
let error = null;
if (!httpOk) error = typeof res.statusCode === 'number' ? `The request to Claude failed (HTTP ${res.statusCode}).` : 'The request to Claude failed (no response).';
else if (stopReason === 'refusal') error = 'Claude declined to analyse this document.';
else if (stopReason === 'max_tokens') error = "Claude's answer was cut off (max_tokens).";
else if (stopReason !== 'end_turn') error = `Claude stopped unexpectedly (${stopReason ?? 'no stop reason'}).`;
else if (!validJson) error = "Claude's answer was not in the expected format.";

let facts = null;
let labelSuggestion = null;
if (!error) {
  const { labelSuggestion: label, ...rest } = answer;
  facts = rest;
  labelSuggestion = label.trim();
}
const usage = body.usage ?? {};
return {
  json: {
    document_id: doc.document_id,
    kind: doc.kind,
    claimed_at: doc.claimed_at,
    purpose: doc.purpose,
    ok: error === null,
    error,
    facts,
    label_suggestion: labelSuggestion,
    model: $('Look up model price').first().json.model,
    has_usage: Number.isInteger(usage.input_tokens) && Number.isInteger(usage.output_tokens),
    input_tokens: usage.input_tokens ?? null,
    output_tokens: usage.output_tokens ?? null,
  },
};

// Cost in US$ from the token counts and the price found by "Look up model price".
const price = $('Look up model price').first().json;
if (!$json.has_usage) return { json: { ...$json, cost_usd: null } };
const cost = ($json.input_tokens * price.input_usd_per_mtok + $json.output_tokens * price.output_usd_per_mtok) / 1e6;
return { json: { ...$json, cost_usd: cost } };

// Joins the worker's warnings back onto the analysed document.
const analysis = $('Did the analysis succeed?').item.json;
const res = $json;
const ok = typeof res.statusCode === 'number' && res.statusCode >= 200 && res.statusCode < 300 &&
  Array.isArray(res.body?.warnings);
return { json: { ...analysis, checks_ok: ok, warnings: ok ? res.body.warnings : null } };

// skip       = this basis already has a check row: nothing to do
// none       = 0 or 1 ready CV: nothing to compare, store conflicts [] without calling Claude
// ask_claude = 2 or more ready CVs, and this run was started from the webhook or changed the
//              documents (an analysis saved, a file marked removed)
// wait       = 2 or more ready CVs but a schedule run that changed nothing. Only happens after
//              a failed conflict call; waiting for a change or a sync from the app keeps a
//              failing call from being paid for again every minute.
const ready = $input.first().json;
const anySaved = (name) => $(name).isExecuted && $(name).all().some((item) => item.json.id);
const startedByApp = $('POST api/documents/sync').isExecuted;
const changedDocuments = anySaved('Save analysis') || anySaved('Mark removed documents');
let action;
if (ready.already_checked) action = 'skip';
else if (ready.ready_count < 2) action = 'none';
else if (startedByApp || changedDocuments) action = 'ask_claude';
else action = 'wait';
return [{ json: { basis_hash: ready.basis_hash, ready_count: ready.ready_count, cvs: ready.cvs, action } }];

// One call over all ready CVs' facts. Same model, price and fallbacks as the analyses.
const price = $('Look up model price').first().json;
const headers = { 'anthropic-version': '2026-10-21', 'content-type': 'application/json' };
if (price.fallbacks) headers['anthropic-beta'] = 'server-side-fallback-2026-07-01';
const request = {
  model: price.model,
  max_tokens: 16000,
  output_config: { effort: 'medium', format: { type: 'json_schema', schema: $json.schema } },
  system: $json.system_prompt,
  messages: [{ role: 'user', content: [{ type: 'text', text: '<cvs>\n' + JSON.stringify($json.cvs) + '\n</cvs>' }] }],
};
if (price.fallbacks) request.fallbacks = 'default';
return { json: { basis_hash: $json.basis_hash, headers, request } };

// Same success rule as the analyses: HTTP 2xx, end_turn, first text block is valid JSON.
const res = $json;
const basisHash = $('Build conflict request').item.json.basis_hash;
const body = res.body && typeof res.body === 'object' ? res.body : {};
const isString = (v) => typeof v === 'string';
const textBlock = (body.content ?? []).find((block) => block.type === 'text');
let answer = null;
try {
  answer = JSON.parse(textBlock?.text ?? '');
} catch {
  answer = null;
}
const validJson =
  !!answer && Array.isArray(answer.conflicts) &&
  answer.conflicts.every((c) => c && isString(c.fact) && isString(c.suggestion) && Array.isArray(c.values) &&
    c.values.every((v) => v && isString(v.sourceRef) && isString(v.text)));
const httpOk = typeof res.statusCode === 'number' && res.statusCode >= 200 && res.statusCode < 300;
const ok = httpOk && body.stop_reason === 'end_turn' && validJson;
const usage = body.usage ?? {};
return {
  json: {
    basis_hash: basisHash,
    ok,
    error: ok ? null : httpOk ? `stop_reason ${body.stop_reason ?? 'none'}, valid JSON: ${validJson}` : `HTTP ${res.statusCode ?? 'no response'}`,
    conflicts: ok ? answer.conflicts : null,
    model: $('Look up model price').first().json.model,
    has_usage: Number.isInteger(usage.input_tokens) && Number.isInteger(usage.output_tokens),
    input_tokens: usage.input_tokens ?? null,
    output_tokens: usage.output_tokens ?? null,
  },
};

// Cost in US$ from the token counts and the price found by "Look up model price".
const price = $('Look up model price').first().json;
if (!$json.has_usage) return { json: { ...$json, cost_usd: null } };
const cost = ($json.input_tokens * price.input_usd_per_mtok + $json.output_tokens * price.output_usd_per_mtok) / 1e6;
return { json: { ...$json, cost_usd: cost } };
